using AdDatabase.API.Hubs;using AdDatabase.API.Mapping;using AdDatabase.API.Middleware;using AdDatabase.BLL.Entities;using AdDatabase.BLL.Interfaces;using AdDatabase.BLL.Models;using AdDatabase.BLL.Services;using AdDatabase.DAL;using AdDatabase.DAL.Data;using Microsoft.EntityFrameworkCore;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.AspNetCore.Identity;using Microsoft.IdentityModel.Tokens;using Microsoft.OpenApi.Models;using Serilog;using System.Text;using System.Text.Json.Serialization;
Log.Logger=new LoggerConfiguration().WriteTo.Console().CreateLogger();try{var builder=WebApplication.CreateBuilder(args);builder.Host.UseSerilog();builder.Services.Configure<JwtOptions>(builder.Configuration.GetSection("Jwt"));var jwt=builder.Configuration.GetSection("Jwt").Get<JwtOptions>()??throw new InvalidOperationException("JWT configuration missing");if(Encoding.UTF8.GetByteCount(jwt.Secret)<32)throw new InvalidOperationException("JWT secret must be at least 32 bytes");builder.Services.AddDataAccess(builder.Configuration);builder.Services.AddScoped<IAuthService,AuthService>();builder.Services.AddScoped<IAdService,AdService>();builder.Services.AddScoped<IConversationService,ConversationService>();builder.Services.AddScoped<IPasswordHasher<User>,PasswordHasher<User>>();builder.Services.AddAutoMapper(typeof(MappingProfile));builder.Services.AddSignalR();builder.Services.AddCors(o=>o.AddPolicy("Frontend",p=>p.WithOrigins(builder.Configuration["FrontendUrl"]??"http://localhost:4200").AllowAnyHeader().AllowAnyMethod().AllowCredentials()));builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>{o.TokenValidationParameters=new(){ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer=jwt.Issuer,ValidAudience=jwt.Audience,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt.Secret)),ClockSkew=TimeSpan.FromSeconds(30)};o.Events=new JwtBearerEvents{OnMessageReceived=c=>{var token=c.Request.Query["access_token"];if(!string.IsNullOrEmpty(token)&&c.HttpContext.Request.Path.StartsWithSegments("/hubs/chat"))c.Token=token;return Task.CompletedTask;}};});builder.Services.AddAuthorization();builder.Services.AddControllers().AddJsonOptions(o=>o.JsonSerializerOptions.ReferenceHandler=ReferenceHandler.IgnoreCycles);builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(o=>{o.SwaggerDoc("v1",new(){Title="Ad Marketplace API",Version="v1"});o.AddSecurityDefinition("Bearer",new(){Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT"});o.AddSecurityRequirement(new(){{new(){Reference=new(){Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});builder.Services.AddHealthChecks();var app=builder.Build();using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();db.Database.EnsureCreated();}app.UseMiddleware<ExceptionMiddleware>();if(app.Environment.IsDevelopment())app.UseSwagger();app.UseSwaggerUI();app.UseHttpsRedirection();app.UseStaticFiles();app.UseCors("Frontend");app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.MapHub<ChatHub>("/hubs/chat");app.MapHealthChecks("/health");app.Run();}catch(Exception e){Log.Fatal(e,"Application terminated");}finally{Log.CloseAndFlush();}
